function shuffleNames($names) {
    shuffle($names);
    return $names;
}

// Function to assign names to tables
function assignToTables($names) {
    $tables = [[]];
    for ($i = 0; $i < 10; $i++) {
        $tables[$i] = array_slice($names, $i * 10, 10);
    }
    return $tables;
}

// Function to check if two arrays have common values
function haveCommonValues($arr1, $arr2) {
    return count(array_intersect($arr1, $arr2)) > 0;
}

// Iterate and assign names to new tables
$iteration = 1;
$previousTables = [];
$currentTables = assignToTables(shuffleNames($names));

while ($iteration < 3) {
    $previousTables = $currentTables;
    $currentTables = assignToTables(shuffleNames($names));

    for ($i = 0; $i < 10; $i++) {
        while (haveCommonValues($previousTables[$i], $currentTables[$i])) {
            $currentTables = assignToTables(shuffleNames($names));
        }
    }
    $iteration++;
    echo "Iteration $iteration done.\n";
}

// Display the tables
