First, install OpenZeppelin Contracts library (if not already installed) using npm:
```
npm install @openzeppelin/contracts
```

Now, here is a simple example of the smart contract:

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import "@openzeppelin/contracts/token/ERC1155/ERC1155.sol";
import "@openzeppelin/contracts/utils/Counters.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract NFTStaking is ERC1155, Ownable {
    using Counters for Counters.Counter;

    IERC721 public nftToken;
    Counters.Counter private _randomItemIds;

    // tokenId => timestamp
    mapping(uint256 => uint256) public lastMintedTime;

    constructor(address nftTokenAddress, string memory uri) ERC1155(uri) {
        nftToken = IERC721(nftTokenAddress);
    }

    // Stake NFT token
    function stake(uint256 tokenId) public {
        nftToken.transferFrom(msg.sender, address(this), tokenId);
    }

    // Unstake NFT token
    function unstake(uint256 tokenId) public {
        require(nftToken.ownerOf(tokenId) == address(this), "Token not staked");
        nftToken.transferFrom(address(this), msg.sender, tokenId);
    }

    // Mint random ERC1155 token if NFT staked for 24 hours
    function mintRandomERC1155(uint256 tokenId) public {
        require(nftToken.ownerOf(tokenId) == msg.sender, "Token not owned by sender");
        require(block.timestamp >= lastMintedTime[tokenId] + 1 days, "24 hours have not passed");

        uint256 newItemId = _random();
        _mint(msg.sender, newItemId, 1, "");
        lastMintedTime[tokenId] = block.timestamp;
    }

    function _random() internal returns (uint256) {
        _randomItemIds.increment();
        return _randomItemIds.current();
    }

    // In case of stuck NFTs
    function recoverStuckNFT(uint256 tokenId, address to) external onlyOwner {
        require(nftToken.ownerOf(tokenId) == address(this), "Token not staked");
        nftToken.transferFrom(address(this), to, tokenId);
    }
}
```

This contract supports staking an ERC721 token (NFT) and minting a random ERC1155 token every 24 hours while staked. You can customize the logic as needed. This contract should be tested extensively and audited before use in a production environment.

