Javascript (script.js):
```javascript
const buttonElement = document.getElementById('my-button');
const headingElement = document.getElementById('my-heading');
const inputElement = document.getElementById('my-input');
const bodyElement = document.body;

const elements = [buttonElement, headingElement, inputElement, bodyElement];

function highlight(element) {
    element.classList.add('highlight');
}

function removeHighlight(element) {
    element.classList.remove('highlight');
}

function removeAllHighlights() {
    elements.forEach(removeHighlight);
}

function handleMouseOver(event) {
    removeAllHighlights();
    highlight(event.target);
}

function handleContextMenu(event) {
    event.preventDefault();
    event.stopPropagation();
    alert(`你用左鍵點擊了 ${event.target.tagName} 元素`);
}

elements.forEach((element) => {
    element.addEventListener('mouseover', handleMouseOver);
    element.addEventListener('contextmenu', handleContextMenu);
});
```

這個範例程式碼中，我們首先創建了HTML結構，添加了button、h1和input標籤。然後，在style標籤中添加了一個.highlight類，當鼠標滑過元素時會應用紅色邊框。接著，在Javascript中，我們使用querySelectorAll選擇元素，設計了highlight、removeHighlight和removeAllHighlights函數來應用和移除邊框，並為每個元素添加了mouseover和contextmenu事件監聽器。

